-- ============================================================
-- SEED EXT 2: Módulo 16 — Advanced Articles (exercícios 71-170)
-- Novos tópicos: the com instituições/organizações, zero article
-- em contextos especiais, artigos com nacionalidades/línguas,
-- artigos em TOEFL Reading e escrita acadêmica
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'articles-advanced';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo articles-advanced não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 11: the com instituições, organizações e organismos geográficos
  (cid,11,71,'gap_fill','She works for _____ United Nations in Geneva.','the',NULL,'"The United Nations" — plural or collective proper nouns with "United" take "the."','easy'),
  (cid,11,72,'multiple_choice','Which institution uses "the"?','The World Health Organization','["Harvard University","The World Health Organization","Stanford University","MIT"]','Acronym-like bodies are often named with "the": The WHO, The UN, The EU, The World Bank.','medium'),
  (cid,11,73,'gap_fill','_____ European Union was established by the Maastricht Treaty in 1993.','The',NULL,'"The European Union" — unions/federations of states use "the."','easy'),
  (cid,11,74,'multiple_choice','Which geographical feature does NOT use "the"?','Lake Baikal','["The Amazon River","The Alps","Lake Baikal","The Pacific Ocean"]','Individual lakes use no article: Lake Baikal, Lake Victoria, Lake Superior.','hard'),
  (cid,11,75,'gap_fill','Researchers at _____ Oxford University published groundbreaking findings on neuroplasticity.','Ø (no article)',NULL,'University names used alone (Oxford, Harvard, Yale, MIT) take no article.','medium'),
  (cid,11,76,'gap_fill','She studied at _____ University of Edinburgh for three years.','the',NULL,'"University of + place" = takes "the": the University of Edinburgh, the University of Tokyo.','medium'),
  (cid,11,77,'multiple_choice','Which pair is CORRECT?','She attended Oxford; he studied at the University of Cambridge.','["She attended the Oxford; he studied at the University of Cambridge.","She attended Oxford; he studied at University of Cambridge.","She attended Oxford; he studied at the University of Cambridge.","She attended the Oxford; he studied at University of Cambridge."]','"Oxford" alone = no article. "The University of Cambridge" = "University of..." pattern.','hard'),
  (cid,11,78,'gap_fill','_____ Black Sea borders six countries and connects to the Mediterranean via the Bosphorus Strait.','The',NULL,'Seas, oceans, rivers, and mountain ranges take "the": The Black Sea, The Alps.','easy'),
  (cid,11,79,'multiple_choice','Which country name takes "the"?','The Philippines','["Brazil","Japan","The Philippines","France"]','"The Philippines" — plural country names take "the": The Philippines, The Netherlands, The United States.','medium'),
  (cid,11,80,'gap_fill','They visited _____ Netherlands during their European research tour.','the',NULL,'"The Netherlands" — plural country names take "the."','medium'),

  -- BLOCK 12: zero article em contextos especiais
  (cid,12,81,'gap_fill','She travels by _____ train to the university every morning.','Ø (no article)',NULL,'Transport with "by": by train, by bus, by car, by plane — no article.','medium'),
  (cid,12,82,'multiple_choice','Which sentence uses NO article correctly?','He went to prison for ten years.','["He went to the prison for ten years (specific prison).","He went to a prison for ten years.","He went to prison for ten years.","He went to prisons for ten years."]','"Go to prison" (as a concept/institution) = no article. "The prison" = a specific building.','hard'),
  (cid,12,83,'gap_fill','She was admitted to _____ hospital after the accident. (as a patient — institution concept)','Ø (no article)',NULL,'"In hospital / to hospital" (British English) = as a patient. "The hospital" = specific building.','hard'),
  (cid,12,84,'multiple_choice','Which sentence uses the zero article correctly?','Breakfast is served from 7 to 10 a.m.','["The breakfast is served from 7 to 10 a.m.","A breakfast is served from 7 to 10 a.m.","Breakfast is served from 7 to 10 a.m.","This breakfast is served from 7 to 10 a.m."]','Meals in general: breakfast, lunch, dinner — no article.','easy'),
  (cid,12,85,'gap_fill','She plays _____ tennis every Saturday morning.','Ø (no article)',NULL,'Sports and games: no article (play tennis, play chess, play football).','easy'),
  (cid,12,86,'gap_fill','He is studying _____ biology at postgraduate level.','Ø (no article)',NULL,'Academic subjects/disciplines: no article (study biology, major in economics, pursue physics).','easy'),
  (cid,12,87,'multiple_choice','Which sentence INCORRECTLY uses an article?','She is learning the piano.','["She is learning the piano (instrument with ''the'' = correct).","She plays the violin every day (instrument = correct).","She studies a biology at university.","She studies biology at university."]','"A biology" is wrong — academic subjects take no article.','medium'),
  (cid,12,88,'gap_fill','___ life is full of unexpected challenges. (general philosophical statement)','Ø (no article)',NULL,'"Life" as an abstract general concept: no article.','medium'),

  -- BLOCK 13: artigos com línguas e nacionalidades
  (cid,13,89,'gap_fill','She speaks _____ English and _____ French fluently.','Ø / Ø',NULL,'Languages do not take articles when used as objects (speak English, learn Spanish).','easy'),
  (cid,13,90,'multiple_choice','Which sentence is correct?','The French are known for their culinary traditions.','["French are known for their culinary traditions.","A French are known for their culinary traditions.","The French are known for their culinary traditions.","Frenchs are known for their culinary traditions."]','"The + nationality adjective" = the people of that nation (The French = French people). Takes "the."','medium'),
  (cid,13,91,'gap_fill','_____ Spanish spoken in Latin America differs from _____ Spanish spoken in Spain.','The / the',NULL,'"The Spanish spoken in X" = specific variety of Spanish (defined by location) → takes "the."','hard'),
  (cid,13,92,'multiple_choice','When does a language name take "the"?','When it refers to a specific variety: "The English of Shakespeare."','["Always","Never","When it refers to a specific variety: ''The English of Shakespeare.''","Only when it is an adjective"]','Languages alone = no article. Specific defined variant + "of" = "the."','hard'),
  (cid,13,93,'gap_fill','_____ Japanese use an alphabet-based writing system. (the Japanese people)','The',NULL,'"The Japanese" = the people. Compare: "Japanese is spoken by 125 million people" (no article = language).','medium'),
  (cid,13,94,'multiple_choice','Which is INCORRECT?','The English is my second language.','["English is my second language.","She speaks the English of the Victorian era (specific).","I''m learning English.","The English is my second language."]','"The English" as a second language is wrong — just "English" (no article for languages used generally).','hard'),

  -- BLOCK 14: artigos em escrita acadêmica
  (cid,14,95,'gap_fill','_____ study of climate change requires interdisciplinary collaboration. (this field of study in general)','The',NULL,'"The study of" = refers to the academic discipline. "The" = specific field of academic inquiry.','medium'),
  (cid,14,96,'multiple_choice','In academic writing, when is "the" used with an abstract noun?','When the abstract noun is particularized by a phrase or clause.','["Always","Never","When the abstract noun is particularized by a phrase or clause.","Only with countable nouns"]','"The evidence from this study" (specific evidence) vs. "Evidence is important" (general concept).','hard'),
  (cid,14,97,'gap_fill','___ evidence gathered in this study supports the hypothesis. (specific evidence from this particular study)','The',NULL,'"The evidence gathered" — "gathered in this study" makes the evidence specific → the.','medium'),
  (cid,14,98,'multiple_choice','Which sentence uses articles correctly in an academic context?','The results of the experiment support the hypothesis that social inequality affects educational outcomes.','["A results of an experiment support a hypothesis that social inequality affects educational outcomes.","The results of the experiment support the hypothesis that social inequality affects educational outcomes.","Results of experiment support hypothesis that social inequality affects educational outcomes.","The results of experiment support a hypothesis that social inequality affect educational outcomes."]','Specific results/experiment/hypothesis = the. Pattern: the results of THE experiment.','hard'),
  (cid,14,99,'gap_fill','___ data presented in Table 3 reveal a significant correlation between the variables.','The',NULL,'"The data presented in Table 3" — defined by location/table → "the."','medium'),
  (cid,14,100,'multiple_choice','Which abstract noun requires "the" in this sentence: "___ poverty discussed in this report is extreme even by regional standards."','The poverty discussed (specific/defined by the clause)','["Poverty in general requires the","The poverty discussed (specific/defined by the clause)","A poverty is always wrong","All abstract nouns need the in academic writing"]','Postmodifier (discussed in this report) defines the noun → "the."','hard'),

  -- BLOCK 15: TOEFL Reading — artigos em textos acadêmicos
  (cid,15,101,'multiple_choice','[TOEFL Reading] "The development of the printing press transformed the dissemination of knowledge." Why "the" before "development"?','It refers to a specific historical development (Gutenberg''s invention), already known in context.','["Development is always countable","It refers to a specific historical development (Gutenberg''s invention), already known in context.","Abstract nouns always take the","It is the first mention of development"]','"The development" = specific (of the printing press, a defined event in history).','medium'),
  (cid,15,102,'gap_fill','[TOEFL Reading] "___ rise of nationalism in the 19th century reshaped political boundaries across Europe." Best article?','The',NULL,'"The rise of nationalism" = specific historical phenomenon being analyzed in the passage.','easy'),
  (cid,15,103,'multiple_choice','[TOEFL Reading] "A new species of deep-sea fish was discovered near the Pacific trench. The species has since been classified within an existing genus." Why switch from "a" to "the"?','First mention = "a" (new/indefinite); second mention = "the" (now known to both reader and writer).','["Because it is now plural","First mention = ''a'' (new/indefinite); second mention = ''the'' (now known to both reader and writer).","Because it is near the Pacific trench","Because it was classified into a genus"]','Article progression: a (first mention) → the (second mention, now identified).','medium'),
  (cid,15,104,'gap_fill','[TOEFL Reading] "Researchers studied ___ relationship between sleep quality and cognitive performance." Best article?','the',NULL,'"The relationship" = specific relationship that the study investigated (defined by context).','medium'),
  (cid,15,105,'multiple_choice','[TOEFL Reading] "Deforestation poses a serious threat to biodiversity." Why no article before "deforestation"?','It is used as an abstract concept in a general statement.','["It is a proper noun","It has never been mentioned before","It is used as an abstract concept in a general statement.","Deforestation is always uncountable so no article"]','General abstract concept in a topic sentence → zero article.','medium'),

  -- BLOCK 16: TOEFL Speaking production
  (cid,16,106,'production','[TOEFL Speaking — 45s] Describe the role of the Internet in modern education. Use "the" correctly for the Internet, the impact, the students, and specific examples with "a/an" for first mentions.','',NULL,'The Internet has fundamentally changed the way students access information. A student today can find a research paper, a lecture, or a tutorial within seconds. The convenience this offers is unprecedented. However, the quality of information found online varies enormously, which is why the development of digital literacy skills is now essential.','medium'),
  (cid,16,107,'production','[TOEFL Speaking — 45s] Discuss whether universities should teach languages. Use articles correctly for: language names (no article), the study of languages (the), nationality groups (the + nationality).','',NULL,'The study of foreign languages should be a core component of university education. English is already widely taught, but the Chinese, the Arabic-speaking world, and the Spanish-speaking community represent growing economic and cultural forces. Learning a language deepens understanding of a culture. Universities that require the study of at least one foreign language produce graduates better prepared for a globalized world.','hard'),

  -- BLOCK 17: TOEFL Writing production
  (cid,17,108,'production','[TOEFL Writing] Write 5 sentences about globalization using articles correctly. Include: the (specific/defined noun), Ø (abstract concept), a/an (first mention), the (second mention), and Ø (language/institution without the).','',NULL,'Globalization has transformed international trade. The growth of digital communication networks has accelerated this process significantly. A company in Brazil can now partner with a firm in South Korea with relative ease. The partnership can then be managed remotely via shared platforms. Languages like English and Mandarin have become essential tools for global business.','hard'),
  (cid,17,109,'production','[TOEFL Writing — Error Correction] Fix all article errors: "A university must invest in the education. The science is important for society. She studies the physics at the MIT. The poverty is a worldwide problem. She was admitted to the hospital last night."','',NULL,'A university = OK; the education → education (general); The science → Science (general); the physics → physics (discipline, no article); the MIT → MIT (proper noun, no article); The poverty → Poverty (general abstract); to the hospital = OK (specific building) OR to hospital (British, institutional concept — both accepted in context.','hard'),
  (cid,17,110,'production','[TOEFL Writing — 150 words] Write a paragraph on "The role of technology in healthcare." Use at least 5 different article uses: the (specific), Ø (abstract/general), a/an (first mention/classification), the (second mention), and the (superlative or unique). Underline each article.','',NULL,'Technology has transformed healthcare in ways that previous generations could not have imagined. A patient who once needed to travel hours to consult a specialist can now access the same expertise via a video call. The consultation can be recorded, shared, and analyzed by multiple physicians simultaneously. Artificial intelligence now assists in diagnosing conditions that human doctors might otherwise miss. The accuracy of AI-assisted diagnosis is, in some cases, superior to that of the most experienced radiologists. Healthcare systems that integrate technology effectively tend to achieve better outcomes at lower cost. Ultimately, the future of medicine depends on the responsible, equitable deployment of technology across all populations, not only the wealthiest.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
